def value_consistent_with_xsd_type(
    value: str, value_type: our_types.DataTypeDefXSD
) -> bool:
    """
    Check that the :paramref:`value` conforms to its :paramref:`value_type`.

    :param value: which needs to conform
    :param value_type: pre-defined value type
    :return: True if the :paramref:`value` conforms
    """
    if value_type == our_types.DataTypeDefXSD.ANY_URI:
        return matches_xs_any_uri(value)
    elif value_type == our_types.DataTypeDefXSD.BASE_64_BINARY:
        return matches_xs_base_64_binary(value)
    elif value_type == our_types.DataTypeDefXSD.BOOLEAN:
        return matches_xs_boolean(value)
    elif value_type == our_types.DataTypeDefXSD.BYTE:
        return is_xs_byte(value)
    elif value_type == our_types.DataTypeDefXSD.DATE:
        return is_xs_date(value)
    elif value_type == our_types.DataTypeDefXSD.DATE_TIME:
        return is_xs_date_time(value)
    elif value_type == our_types.DataTypeDefXSD.DECIMAL:
        return matches_xs_decimal(value)
    elif value_type == our_types.DataTypeDefXSD.DOUBLE:
        return is_xs_double(value)
    elif value_type == our_types.DataTypeDefXSD.DURATION:
        return matches_xs_duration(value)
    elif value_type == our_types.DataTypeDefXSD.FLOAT:
        return is_xs_float(value)
    elif value_type == our_types.DataTypeDefXSD.G_DAY:
        return matches_xs_g_day(value)
    elif value_type == our_types.DataTypeDefXSD.G_MONTH:
        return matches_xs_g_month(value)
    elif value_type == our_types.DataTypeDefXSD.G_MONTH_DAY:
        return is_xs_g_month_day(value)
    elif value_type == our_types.DataTypeDefXSD.G_YEAR:
        return matches_xs_g_year(value)
    elif value_type == our_types.DataTypeDefXSD.G_YEAR_MONTH:
        return matches_xs_g_year_month(value)
    elif value_type == our_types.DataTypeDefXSD.HEX_BINARY:
        return matches_xs_hex_binary(value)
    elif value_type == our_types.DataTypeDefXSD.INT:
        return is_xs_int(value)
    elif value_type == our_types.DataTypeDefXSD.INTEGER:
        return matches_xs_integer(value)
    elif value_type == our_types.DataTypeDefXSD.LONG:
        return is_xs_long(value)
    elif value_type == our_types.DataTypeDefXSD.NEGATIVE_INTEGER:
        return matches_xs_negative_integer(value)
    elif value_type == our_types.DataTypeDefXSD.NON_NEGATIVE_INTEGER:
        return matches_xs_non_negative_integer(value)
    elif value_type == our_types.DataTypeDefXSD.NON_POSITIVE_INTEGER:
        return matches_xs_non_positive_integer(value)
    elif value_type == our_types.DataTypeDefXSD.POSITIVE_INTEGER:
        return matches_xs_positive_integer(value)
    elif value_type == our_types.DataTypeDefXSD.SHORT:
        return is_xs_short(value)
    elif value_type == our_types.DataTypeDefXSD.STRING:
        return matches_xs_string(value)
    elif value_type == our_types.DataTypeDefXSD.TIME:
        return matches_xs_time(value)
    elif value_type == our_types.DataTypeDefXSD.UNSIGNED_BYTE:
        return is_xs_unsigned_byte(value)
    elif value_type == our_types.DataTypeDefXSD.UNSIGNED_INT:
        return is_xs_unsigned_int(value)
    elif value_type == our_types.DataTypeDefXSD.UNSIGNED_LONG:
        return is_xs_unsigned_long(value)
    elif value_type == our_types.DataTypeDefXSD.UNSIGNED_SHORT:
        return is_xs_unsigned_short(value)
    return False


def is_model_reference_to(
    reference: our_types.Reference, expected_type: our_types.KeyTypes
) -> bool:
    """
    Check that the target of the model reference matches the :paramref:`expected_type`.
    """
    return (
        reference.type == our_types.ReferenceTypes.MODEL_REFERENCE
        and len(reference.keys) != 0
        and reference.keys[-1].type == expected_type
    )


def is_model_reference_to_referable(reference: our_types.Reference) -> bool:
    """
    Check that the target of the reference matches a :py:attr:`.constants.AAS_REFERABLES`.
    """
    return (
        reference.type == our_types.ReferenceTypes.MODEL_REFERENCE
        and len(reference.keys) != 0
        and (reference.keys[-1].type in our_constants.AAS_REFERABLES)
    )


def id_shorts_are_unique(referables: Sequence[our_types.Referable]) -> bool:
    """
    Check that the :py:attr:`.types.Referable.id_short`'s among the :paramref:`referables` are
    unique in their namespace.
    """
    id_short_set: Set[str] = set()
    for referable in referables:
        id_short = referable.id_short
        if id_short is None:
            continue
        if id_short in id_short_set:
            return False
        id_short_set.add(id_short)
    return True


def _collect_unique_id_shorts_of_variables(
    variables: Optional[Sequence[our_types.OperationVariable]], id_short_set: Set[str]
) -> bool:
    """
    Collect the :py:attr:`.types.Referable.id_short`'s of the :paramref:`variables` values.

    :param variables:
        Operation variables whose ID-shorts we collect
    :param id_short_set:
        ID-shorts observed so far, extended in place
    :return: False if an ID-short has been already observed
    """
    if variables is None:
        return True
    for variable in variables:
        id_short = variable.value.id_short
        if id_short is None:
            continue
        if id_short in id_short_set:
            return False
        id_short_set.add(id_short)
    return True


def id_shorts_of_variables_are_unique(
    input_variables: Optional[Sequence[our_types.OperationVariable]],
    output_variables: Optional[Sequence[our_types.OperationVariable]],
    inoutput_variables: Optional[Sequence[our_types.OperationVariable]],
) -> bool:
    """
    Check that the :py:attr:`.types.Referable.id_short`'s among all the
    :paramref:`input_variables`, :paramref:`output_variables`
    and :paramref:`inoutput_variables` are unique.
    """
    id_short_set: Set[str] = set()
    return (
        _collect_unique_id_shorts_of_variables(input_variables, id_short_set)
        and _collect_unique_id_shorts_of_variables(output_variables, id_short_set)
        and _collect_unique_id_shorts_of_variables(inoutput_variables, id_short_set)
    )


# noinspection SpellCheckingInspection
def _construct_specific_asset_id_name_matches_global_asset_id() -> Pattern[str]:
    pattern = "^[gG][lL][oO][bB][aA][lL][aA][sS][sS][eE][tT][iI][dD]$"

    return re.compile(pattern)


_REGEX_SPECIFIC_ASSET_ID_NAME_MATCHES_GLOBAL_ASSET_ID = (
    _construct_specific_asset_id_name_matches_global_asset_id()
)


def specific_asset_id_name_matches_global_asset_id(name: str) -> bool:
    """
    Check whether :paramref:`name` is the reserved global asset ID key.
    """
    return _REGEX_SPECIFIC_ASSET_ID_NAME_MATCHES_GLOBAL_ASSET_ID.match(name) is not None


def submodel_element_has_template_qualifier_in_tree(
    element: our_types.SubmodelElement,
) -> bool:
    """
    Check whether :paramref:`element` or its descendants have template qualifiers.
    """
    if (element.qualifiers is not None) and (
        any(
            qualifier.kind_or_default() == our_types.QualifierKind.TEMPLATE_QUALIFIER
            for qualifier in element.qualifiers
        )
    ):
        return True
    if isinstance(element, our_types.SubmodelElementList):
        return (element.value is not None) and (
            any(
                submodel_element_has_template_qualifier_in_tree(child)
                for child in element.value
            )
        )
    if isinstance(element, our_types.SubmodelElementCollection):
        return (element.value is not None) and (
            any(
                submodel_element_has_template_qualifier_in_tree(child)
                for child in element.value
            )
        )
    if isinstance(element, our_types.Entity):
        return (element.statements is not None) and (
            any(
                submodel_element_has_template_qualifier_in_tree(child)
                for child in element.statements
            )
        )
    if isinstance(element, our_types.AnnotatedRelationshipElement):
        return (element.annotations is not None) and (
            any(
                submodel_element_has_template_qualifier_in_tree(child)
                for child in element.annotations
            )
        )
    if isinstance(element, our_types.Operation):
        pass
    return False


def submodel_elements_have_no_template_qualifiers(
    elements: Sequence[our_types.SubmodelElement],
) -> bool:
    """
    Check that :paramref:`elements` have no template qualifiers in their trees.
    """
    return all(
        not submodel_element_has_template_qualifier_in_tree(element)
        for element in elements
    )


def submodel_element_lists_have_exactly_one_element_in_tree(
    element: our_types.SubmodelElement,
) -> bool:
    """
    Recursively check that submodel element lists have exactly one child.
    """
    if isinstance(element, our_types.SubmodelElementList):
        return (
            (element.value is not None)
            and len(element.value) == 1
            and (
                all(
                    submodel_element_lists_have_exactly_one_element_in_tree(child)
                    for child in element.value
                )
            )
        )
    if isinstance(element, our_types.SubmodelElementCollection):
        return (element.value is None) or (
            all(
                submodel_element_lists_have_exactly_one_element_in_tree(child)
                for child in element.value
            )
        )
    if isinstance(element, our_types.Entity):
        return (element.statements is None) or (
            all(
                submodel_element_lists_have_exactly_one_element_in_tree(child)
                for child in element.statements
            )
        )
    if isinstance(element, our_types.AnnotatedRelationshipElement):
        return (element.annotations is None) or (
            all(
                submodel_element_lists_have_exactly_one_element_in_tree(child)
                for child in element.annotations
            )
        )
    return True


def submodel_element_lists_in_submodel_elements_have_exactly_one_element(
    elements: Sequence[our_types.SubmodelElement],
) -> bool:
    """
    Check that all submodel element lists among :paramref:`elements` have one item.
    """
    return all(
        submodel_element_lists_have_exactly_one_element_in_tree(element)
        for element in elements
    )


def submodel_element_lists_in_operation_variables_have_exactly_one_element(
    input_variables: Optional[Sequence[our_types.OperationVariable]],
    output_variables: Optional[Sequence[our_types.OperationVariable]],
    inoutput_variables: Optional[Sequence[our_types.OperationVariable]],
) -> bool:
    """
    Check that submodel element lists in operation variables have one item.
    """
    return (
        (
            (
                (input_variables is None)
                or (
                    all(
                        submodel_element_lists_have_exactly_one_element_in_tree(
                            variable.value
                        )
                        for variable in input_variables
                    )
                )
            )
        )
        and (
            (
                (output_variables is None)
                or (
                    all(
                        submodel_element_lists_have_exactly_one_element_in_tree(
                            variable.value
                        )
                        for variable in output_variables
                    )
                )
            )
        )
        and (
            (
                (inoutput_variables is None)
                or (
                    all(
                        submodel_element_lists_have_exactly_one_element_in_tree(
                            variable.value
                        )
                        for variable in inoutput_variables
                    )
                )
            )
        )
    )


def extension_names_are_unique(extensions: Sequence[our_types.Extension]) -> bool:
    """Check that the extension names are unique."""
    name_set: Set[str] = set()
    for extension in extensions:
        if extension.name in name_set:
            return False
        name_set.add(extension.name)
    return True


def submodel_elements_have_identical_semantic_ids(
    elements: Sequence[our_types.SubmodelElement],
) -> bool:
    """Check that all semantic IDs are identical, if specified."""
    that_semantic_id: Optional[our_types.Reference] = None
    for element in elements:
        this_semantic_id = element.semantic_id
        if this_semantic_id is None:
            continue
        if that_semantic_id is None:
            that_semantic_id = this_semantic_id
        elif not reference_key_values_equal(that_semantic_id, this_semantic_id):
            return False
    return True


def submodel_element_is_of_type(
    element: our_types.SubmodelElement, element_type: our_types.AASSubmodelElements
) -> bool:
    """
    Check that the run-time type of the :paramref:`element` coincides with
    :paramref:`element_type`.
    """
    if element_type == our_types.AASSubmodelElements.ANNOTATED_RELATIONSHIP_ELEMENT:
        return isinstance(element, our_types.AnnotatedRelationshipElement)
    elif element_type == our_types.AASSubmodelElements.BASIC_EVENT_ELEMENT:
        return isinstance(element, our_types.BasicEventElement)
    elif element_type == our_types.AASSubmodelElements.BLOB:
        return isinstance(element, our_types.Blob)
    elif element_type == our_types.AASSubmodelElements.CAPABILITY:
        return isinstance(element, our_types.Capability)
    elif element_type == our_types.AASSubmodelElements.DATA_ELEMENT:
        return isinstance(element, our_types.DataElement)
    elif element_type == our_types.AASSubmodelElements.ENTITY:
        return isinstance(element, our_types.Entity)
    elif element_type == our_types.AASSubmodelElements.EVENT_ELEMENT:
        return isinstance(element, our_types.EventElement)
    elif element_type == our_types.AASSubmodelElements.FILE:
        return isinstance(element, our_types.File)
    elif element_type == our_types.AASSubmodelElements.MULTI_LANGUAGE_PROPERTY:
        return isinstance(element, our_types.MultiLanguageProperty)
    elif element_type == our_types.AASSubmodelElements.OPERATION:
        return isinstance(element, our_types.Operation)
    elif element_type == our_types.AASSubmodelElements.PROPERTY:
        return isinstance(element, our_types.Property)
    elif element_type == our_types.AASSubmodelElements.RANGE:
        return isinstance(element, our_types.Range)
    elif element_type == our_types.AASSubmodelElements.REFERENCE_ELEMENT:
        return isinstance(element, our_types.ReferenceElement)
    elif element_type == our_types.AASSubmodelElements.RELATIONSHIP_ELEMENT:
        return isinstance(element, our_types.RelationshipElement)
    elif element_type == our_types.AASSubmodelElements.SUBMODEL_ELEMENT:
        return True
    elif element_type == our_types.AASSubmodelElements.SUBMODEL_ELEMENT_LIST:
        return isinstance(element, our_types.SubmodelElementList)
    elif element_type == our_types.AASSubmodelElements.SUBMODEL_ELEMENT_COLLECTION:
        return isinstance(element, our_types.SubmodelElementCollection)
    return False


def properties_or_ranges_have_value_type(
    elements: Sequence[our_types.SubmodelElement], value_type: our_types.DataTypeDefXSD
) -> bool:
    """
    Check that all the :paramref:`elements` have the :paramref:`value_type`.
    """
    for element in elements:
        if isinstance(element, our_types.Property) and element.value_type != value_type:
            return False
        if isinstance(element, our_types.Range) and element.value_type != value_type:
            return False
    return True


def reference_key_values_equal(
    that: our_types.Reference, other: our_types.Reference
) -> bool:
    """
    Check that the two references are equal by comparing their key values.
    """
    if len(that.keys) != len(other.keys):
        return False
    for i in range(0, len(that.keys)):
        if that.keys[i].value != other.keys[i].value:
            return False
    return True


def data_specification_iec_61360s_for_property_or_value_have_appropriate_data_type(
    embedded_data_specifications: Sequence[our_types.EmbeddedDataSpecification],
) -> bool:
    """
    Check that the :py:attr:`.types.DataSpecificationIEC61360.data_type` is defined
    appropriately for all data specifications whose content is given as IEC 61360.
    """
    return all(
        not isinstance(
            data_specification.data_specification_content,
            our_types.DataSpecificationIEC61360,
        )
        or (
            (
                (data_specification.data_specification_content.data_type is not None)
                and (
                    data_specification.data_specification_content.data_type
                    in our_constants.DATA_TYPE_IEC_61360_FOR_PROPERTY_OR_VALUE
                )
            )
        )
        for data_specification in embedded_data_specifications
    )


