def data_specification_iec_61360s_have_definition_at_least_in_english(
    embedded_data_specifications: Sequence[our_types.EmbeddedDataSpecification],
) -> bool:
    """
    Check that the :py:attr:`.types.DataSpecificationIEC61360.definition` is defined
    for all data specifications whose content is given as IEC 61360 at least in English.
    """
    for data_specification in embedded_data_specifications:
        content = data_specification.data_specification_content
        if not isinstance(content, our_types.DataSpecificationIEC61360):
            continue
        definition = content.definition
        if definition is None:
            return False
        if not (
            any(
                is_bcp_47_for_english(lang_string.language)
                for lang_string in definition
            )
        ):
            return False
    return True


# noinspection SpellCheckingInspection
def _construct_is_bcp_47_for_english() -> Pattern[str]:
    pattern = "^(en|EN)(-.*)?$"

    return re.compile(pattern)


_REGEX_IS_BCP_47_FOR_ENGLISH = _construct_is_bcp_47_for_english()


def is_bcp_47_for_english(text: str) -> bool:
    """
    Check that the :paramref:`text` corresponds to a BCP47 code for english.
    """
    return _REGEX_IS_BCP_47_FOR_ENGLISH.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_path_item() -> Pattern[str]:
    pattern = "^(([A-Za-z][A-Za-z0-9_]+)|(\\[[0-9]+\\]))((\\.[A-Za-z][A-Za-z0-9_]+)|(\\[[0-9]+\\]))*$"

    return re.compile(pattern)


_REGEX_MATCHES_PATH_ITEM = _construct_matches_path_item()


def matches_path_item(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid idShortPath.

    An idShortPath is a chain of idShorts or SubmodelElementList-indexes
    which points to an element within a hierarchy of elements, *e.g.*,
    ``sme1.sme2[0].p1``.
    """
    return _REGEX_MATCHES_PATH_ITEM.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_field_identifier() -> Pattern[str]:
    array_index = "(0|[1-9][0-9]*)"
    optional_index = f"\\[{array_index}?\\]"
    reference_clause = f"(type|keys{optional_index}\\.(type|value))"
    semantic_id_clause = f"semanticId(\\.{reference_clause})?"
    supplemental_semantic_id_clause = (
        f"supplementalSemanticIds({optional_index})?(\\.{reference_clause})?"
    )
    specific_asset_ids_clause = f"specificAssetIds{optional_index}\\.(name|value|externalSubjectId(\\.{reference_clause})?)"
    endpoint_clause = (
        f"endpoints{optional_index}\\.(interface|protocolinformation\\.href)"
    )
    sm_descriptor_clause = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|id|{endpoint_clause})"
    id_short = "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?"
    id_short_path_segment = f"{id_short}({optional_index})*"
    id_short_path = f"{id_short_path_segment}(\\.{id_short_path_segment})*"
    fields_aas = f"(idShort|id|assetInformation\\.assetKind|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\.{specific_asset_ids_clause}|submodels{optional_index}(\\.{reference_clause})?)"
    fields_sm = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|id)"
    fields_sme = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|value|valueType|language)"
    fields_cd = "(idShort|id)"
    fields_aas_descriptor = f"(idShort|id|assetKind|assetType|globalAssetId|{specific_asset_ids_clause}|{endpoint_clause}|submodelDescriptors{optional_index}\\.{sm_descriptor_clause})"
    pattern = f"^(\\$aas#{fields_aas}|\\$sm#{fields_sm}|\\$sme(\\.{id_short_path})?#{fields_sme}|\\$cd#{fields_cd}|\\$aasdesc#{fields_aas_descriptor}|\\$smdesc#{sm_descriptor_clause})$"

    return re.compile(pattern)


_REGEX_MATCHES_FIELD_IDENTIFIER = _construct_matches_field_identifier()


def matches_field_identifier(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid field identifier of the query language.

    A field identifier starts with a root (``$aas``, ``$sm``, ``$sme``, ``$cd``,
    ``$aasdesc`` or ``$smdesc``), optionally followed by an idShortPath in case
    of ``$sme``, and ends with an attribute declaration after ``#``, *e.g.*,
    ``$sme.someCollection.someProperty#value``.

    See:
    https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar

    :param text: Text to be checked
    :return:
        True if the :paramref:`text` conforms to the pattern
    """
    return _REGEX_MATCHES_FIELD_IDENTIFIER.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_fragment_field_identifier() -> Pattern[str]:
    array_index = "(0|[1-9][0-9]*)"
    optional_index = f"\\[{array_index}?\\]"
    reference_clause = f"keys({optional_index})?"
    semantic_id_clause = f"semanticId(\\.{reference_clause})?"
    supplemental_semantic_id_clause = (
        f"supplementalSemanticIds({optional_index}(\\.{reference_clause})?)?"
    )
    specific_asset_ids_clause = f"specificAssetIds({optional_index}(\\.externalSubjectId(\\.{reference_clause})?)?)?"
    submodels_clause = f"submodels({optional_index}(\\.{reference_clause})?)?"
    endpoint_clause = f"endpoints({optional_index})?"
    sm_descriptor_clause = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|{endpoint_clause})"
    submodel_descriptors_clause = (
        f"submodelDescriptors({optional_index}(\\.{sm_descriptor_clause})?)?"
    )
    id_short = "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?"
    id_short_path_segment = f"{id_short}({optional_index})*"
    id_short_path = f"{id_short_path_segment}(\\.{id_short_path_segment})*"
    fields_aas = f"(idShort|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\.{specific_asset_ids_clause}|{submodels_clause})"
    fields_sm = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort)"
    fields_sme = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|value|valueType|language)"
    fields_aas_descriptor = f"(idShort|description|displayName|extension|administration|assetKind|assetType|globalAssetId|{specific_asset_ids_clause}|{endpoint_clause}|{submodel_descriptors_clause})"
    pattern = f"^(\\$aas#{fields_aas}|\\$sm#{fields_sm}|\\$sme(\\.{id_short_path})?(#{fields_sme})?|\\$cd#idShort|\\$aasdesc#{fields_aas_descriptor}|\\$smdesc#{sm_descriptor_clause})$"

    return re.compile(pattern)


_REGEX_MATCHES_FRAGMENT_FIELD_IDENTIFIER = (
    _construct_matches_fragment_field_identifier()
)


def matches_fragment_field_identifier(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid fragment field identifier.

    A fragment field identifier points to the part of the returned data which
    should be filtered, *e.g.*, ``$aas#assetInformation.specificAssetIds[]``
    or ``$sme.someCollection``.

    See:
    https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar

    :param text: Text to be checked
    :return:
        True if the :paramref:`text` conforms to the pattern
    """
    return _REGEX_MATCHES_FRAGMENT_FIELD_IDENTIFIER.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_hex_literal() -> Pattern[str]:
    pattern = "^16#[0-9A-F]+$"

    return re.compile(pattern)


_REGEX_MATCHES_HEX_LITERAL = _construct_matches_hex_literal()


def matches_hex_literal(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid hexadecimal literal of the query language.

    A hexadecimal literal is prefixed with ``16#``, *e.g.*, ``16#1F``.

    :param text: Text to be checked
    :return:
        True if the :paramref:`text` conforms to the pattern
    """
    return _REGEX_MATCHES_HEX_LITERAL.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_date_time_literal() -> Pattern[str]:
    digit = "[0-9]"
    month_with_31_days = f"(0[13578]|1[02])-(0[1-9]|[12]{digit}|3[01])"
    month_with_30_days = f"(0[469]|11)-(0[1-9]|[12]{digit}|30)"
    february = f"02-(0[1-9]|1{digit}|2[0-8])"
    common_date = f"{digit}{{4}}-({month_with_31_days}|{month_with_30_days}|{february})"
    leap_year = (
        f"({digit}{{2}}(0[48]|[2468][048]|[13579][26])|([02468][048]|[13579][26])00)"
    )
    leap_day = f"{leap_year}-02-29"
    time = f"(([01]{digit}|2[0-3]):[0-5]{digit}(:[0-5]{digit})?(\\.{digit}+)?|24:00(:00)?(\\.0+)?)"
    timezone = f"(Z|[+-]((0{digit}|1[0-3]):[0-5]{digit}|14:00))"
    pattern = f"^(({common_date})|({leap_day}))T?{time}{timezone}?$"

    return re.compile(pattern)


_REGEX_MATCHES_DATE_TIME_LITERAL = _construct_matches_date_time_literal()


def matches_date_time_literal(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid date-time literal of the query language.

    A date-time literal is a valid calendar date, followed by an optional ``T``
    separator, the time and an optional time zone, *e.g.*,
    ``2024-02-29T12:00:00Z``.

    :param text: Text to be checked
    :return:
        True if the :paramref:`text` conforms to the pattern
    """
    return _REGEX_MATCHES_DATE_TIME_LITERAL.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_time_literal() -> Pattern[str]:
    digit = "[0-9]"
    time = f"(([01]{digit}|2[0-3]):[0-5]{digit}(:[0-5]{digit})?(\\.{digit}+)?|24:00(:00)?(\\.0+)?)"
    timezone = f"(Z|[+-]((0{digit}|1[0-3]):[0-5]{digit}|14:00))"
    pattern = f"^{time}{timezone}?$"

    return re.compile(pattern)


_REGEX_MATCHES_TIME_LITERAL = _construct_matches_time_literal()


def matches_time_literal(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid time literal of the query language.

    A time literal is given as ``HH:MM``, ``HH:MM:SS``, optionally with
    fractional seconds and an optional time zone, *e.g.*, ``12:00:00+01:00``.

    :param text: Text to be checked
    :return:
        True if the :paramref:`text` conforms to the pattern
    """
    return _REGEX_MATCHES_TIME_LITERAL.match(text) is not None


# noinspection SpellCheckingInspection
def _construct_matches_reference_identifier() -> Pattern[str]:
    array_index = "(0|[1-9][0-9]*)"
    optional_index = f"\\[{array_index}?\\]"
    reference_clause = f"(type|keys{optional_index}\\.(type|value))"
    semantic_id_clause = f"semanticId(\\.{reference_clause})?"
    supplemental_semantic_id_clause = (
        f"supplementalSemanticIds({optional_index})?(\\.{reference_clause})?"
    )
    specific_asset_ids_clause = f"specificAssetIds{optional_index}\\.(name|value|externalSubjectId(\\.{reference_clause})?)"
    id_short = "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?"
    id_short_path_segment = f"{id_short}({optional_index})*"
    id_short_path = f"{id_short_path_segment}(\\.{id_short_path_segment})*"
    identifier_character = '([\\x09\\x0a\\x0d\\x20-\\x21\\x23-\\x5b\\x5d-\\ud7ff\\ue000-\\ufffd\\U00010000-\\U0010ffff]|\\\\["\\\\])'
    identifier_instance = f'\\("{identifier_character}+"\\)'
    fields_aas = f"(idShort|id|assetInformation\\.assetKind|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\.{specific_asset_ids_clause}|submodels{optional_index}(\\.{reference_clause})?)"
    fields_sm = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|id)"
    fields_sme = f"({semantic_id_clause}|{supplemental_semantic_id_clause}|idShort|value|valueType|language)"
    pattern = f"^(\\$aas{identifier_instance}#{fields_aas}|\\$sm{identifier_instance}#{fields_sm}|\\$cd{identifier_instance}#(idShort|id)|\\$sme{identifier_instance}\\.{id_short_path}#{fields_sme})$"

    return re.compile(pattern)


_REGEX_MATCHES_REFERENCE_IDENTIFIER = _construct_matches_reference_identifier()


def matches_reference_identifier(text: str) -> bool:
    """
    Check that :paramref:`text` is a valid reference identifier.

    A reference identifier points to an attribute of a specific instance given
    by its identifier, *e.g.*, ``$sm("https://example.com/sm")#idShort`` or
    ``$sme("https://example.com/sm").someProperty#value``. A quotation mark and
    a reverse solidus in the identifier are escaped as ``\\"`` and ``\\\\``,
    respectively.

    See:
    https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar

    :param text: Text to be checked
    :return:
        True if the :paramref:`text` conforms to the pattern
    """
    return _REGEX_MATCHES_REFERENCE_IDENTIFIER.match(text) is not None


def _can_be_of_type(value: our_types.Value, value_type: str) -> bool:
    """
    Check that :paramref:`value` can be used as an operand of :paramref:`value_type`.

    Following the normative JSON schema of the query language, a field is
    implicitly cast to the type of the other operand, and can hence be used as
    an operand of any type. A global attribute giving a date and time
    (``LOCALNOW``, ``UTCNOW`` or ``CLIENTNOW``) can be used both as a string and
    as a date-time, while all the other attributes are strings.

    See:
    https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema

    :param value: Operand of a comparison
    :param value_type:
        One of ``string``, ``number``, ``hex``, ``boolean``, ``date_time``
        or ``time``
    :return:
        True if :paramref:`value` can be used as :paramref:`value_type`
    """
    if isinstance(value, our_types.FieldOperand):
        return True
    if isinstance(value, our_types.AttributeOperand):
        if value_type == "string":
            return True
        attribute = value.attribute
        return (
            value_type == "date_time"
            and isinstance(attribute, our_types.GlobalAttribute)
            and (
                (
                    attribute.kind == our_types.GlobalAttributeKind.LOCAL_NOW
                    or attribute.kind == our_types.GlobalAttributeKind.UTC_NOW
                    or attribute.kind == our_types.GlobalAttributeKind.CLIENT_NOW
                )
            )
        )
    if isinstance(value, (our_types.StringLiteral, our_types.StringCast)):
        return value_type == "string"
    if isinstance(
        value,
        (
            our_types.NumberLiteral,
            our_types.NumberCast,
            our_types.DayOfWeek,
            our_types.DayOfMonth,
            our_types.Month,
            our_types.Year,
        ),
    ):
        return value_type == "number"
    if isinstance(value, (our_types.HexLiteral, our_types.HexCast)):
        return value_type == "hex"
    if isinstance(value, (our_types.BooleanLiteral, our_types.BooleanCast)):
        return value_type == "boolean"
    if isinstance(value, (our_types.DateTimeLiteral, our_types.DateTimeCast)):
        return value_type == "date_time"
    if isinstance(value, (our_types.TimeLiteral, our_types.TimeCast)):
        return value_type == "time"
    return False


def are_equality_comparable(left: our_types.Value, right: our_types.Value) -> bool:
    """
    Check that :paramref:`left` and :paramref:`right` can be compared for
    (in)equality.

    Following the normative JSON schema of the query language, the two operands
    need to be of the same type: a string, a number, a hexadecimal, a boolean,
    a date-time or a time. A field is implicitly cast to the type of the other
    operand, and can hence be compared with an operand of any type. A global
    attribute giving a date and time (``LOCALNOW``, ``UTCNOW`` or ``CLIENTNOW``)
    can be used both as a string and as a date-time.

    See:
    https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema

    :param left: First operand of the comparison
    :param right: Second operand of the comparison
    :return:
        True if the operands can be compared for (in)equality
    """
    return (
        ((_can_be_of_type(left, "string") and _can_be_of_type(right, "string")))
        or ((_can_be_of_type(left, "number") and _can_be_of_type(right, "number")))
        or ((_can_be_of_type(left, "hex") and _can_be_of_type(right, "hex")))
        or ((_can_be_of_type(left, "boolean") and _can_be_of_type(right, "boolean")))
        or (
            (_can_be_of_type(left, "date_time") and _can_be_of_type(right, "date_time"))
        )
        or ((_can_be_of_type(left, "time") and _can_be_of_type(right, "time")))
    )


def are_order_comparable(left: our_types.Value, right: our_types.Value) -> bool:
    """
    Check that :paramref:`left` and :paramref:`right` can be compared by order.

    The operands need to be comparable for (in)equality (see
    ``are_equality_comparable``), but booleans can not be ordered.

    See:
    https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema

    :param left: First operand of the comparison
    :param right: Second operand of the comparison
    :return: True if the operands can be compared by order
    """
    return (
        are_equality_comparable(left, right)
        and (not isinstance(left, (our_types.BooleanLiteral, our_types.BooleanCast)))
        and (not isinstance(right, (our_types.BooleanLiteral, our_types.BooleanCast)))
    )


