_TRANSFORMER = _Transformer()


def verify(that: our_types.Class) -> Iterator[Error]:
    """
    Verify the constraints of :paramref:`that` recursively.

    :param that: instance whose constraints we want to verify
    :yield: constraint violations
    """
    yield from _TRANSFORMER.transform(that)


def _verify_list_of__class(that: Sequence[our_types.Class]) -> Iterator[Error]:
    """Verify the items of :paramref:`that` recursively."""
    for i, item in enumerate(that):
        for error in verify(item):
            error.path._prepend(IndexSegment(that, i))
            yield error


def _verify_list_of__name_type(that: Sequence[str]) -> Iterator[Error]:
    """Verify the items of :paramref:`that` recursively."""
    for i, item in enumerate(that):
        for error in verify_name_type(item):
            error.path._prepend(IndexSegment(that, i))
            yield error


def _verify_list_of__identifier(that: Sequence[str]) -> Iterator[Error]:
    """Verify the items of :paramref:`that` recursively."""
    for i, item in enumerate(that):
        for error in verify_identifier(item):
            error.path._prepend(IndexSegment(that, i))
            yield error


def _verify_list_of__json_object(
    that: Sequence[our_types.JsonObject],
) -> Iterator[Error]:
    """Verify the items of :paramref:`that` recursively."""
    for i, item in enumerate(that):
        for error in our_json_value_verification.verify_json_object(item):
            error.path._prepend(IndexSegment(that, i))
            yield error

        for key in item:
            # NOTE (mristin):
            # The key segment names the member whose key is erroneous. The path
            # thus leads to the member, and the cause says what is wrong with
            # the key which names it.
            for error in verify_label_type(key):
                error.path._prepend(KeySegment(item, key))
                error.path._prepend(IndexSegment(that, i))
                yield error


def _verify_list_of__path_item(that: Sequence[str]) -> Iterator[Error]:
    """Verify the items of :paramref:`that` recursively."""
    for i, item in enumerate(that):
        for error in verify_path_item(item):
            error.path._prepend(IndexSegment(that, i))
            yield error


def _verify_tuple2_of__class__class(
    that: Tuple[our_types.Class, our_types.Class],
) -> Iterator[Error]:
    """Verify the items of :paramref:`that` recursively."""
    for error in verify(that[0]):
        error.path._prepend(IndexSegment(that, 0))
        yield error

    for error in verify(that[1]):
        error.path._prepend(IndexSegment(that, 1))
        yield error


